def _socket_response_headers(document: Mapping[str, Any], operation_id: str, action_sequence: int) -> Dict[str, Any]:
    """Add host-bound call proofs after removing untrusted copies."""
    headers = {name: value for name, value in dict(document['headers']).items() if not (isinstance(name, str) and name.lower() in (SETTLED_MICROUSD_HEADER, CALL_IDENTITY_HEADER))}
    call = document.get('call')
    provider_matches = isinstance(call, Mapping) and _call_provider_matches_operation(call, operation_id)
    if isinstance(call, Mapping) and call.get('operation_id') == operation_id and (type(call.get('action_sequence')) is int) and (call['action_sequence'] == action_sequence) and provider_matches and (operation_id not in operations.CATALOG_OPERATIONS) and (type(document.get('status')) is int) and (100 <= document['status'] <= 599) and isinstance(call.get('call_identity'), str) and (contracts.SHA256_RE.fullmatch(call['call_identity']) is not None):
        headers[CALL_IDENTITY_HEADER] = call['call_identity']
    if operation_id != 'deepline.execute':
        return headers
    call = document.get('call')
    if not (isinstance(call, Mapping) and call.get('operation_id') == operation_id and (call.get('provider') == 'deepline') and (type(call.get('action_sequence')) is int) and (call.get('action_sequence') == action_sequence) and isinstance(call.get('call_identity'), str) and (contracts.SHA256_RE.fullmatch(call['call_identity']) is not None)):
        return headers
    headers[CALL_IDENTITY_HEADER] = call['call_identity']
    try:
        body = json.loads(base64.b64decode(str(document['body_b64']), validate=True))
    except (TypeError, ValueError, UnicodeDecodeError):
        return headers
    if not isinstance(body, Mapping):
        return headers
    if not (call.get('outcome') == 'settled' and type(call.get('actual_microusd')) is int and (call.get('actual_microusd') >= 0)):
        return headers
    headers[SETTLED_MICROUSD_HEADER] = str(call['actual_microusd'])
    return headers

