def _parse_worker_response_with_url(payload: Any) -> Tuple[int, Dict[str, str], bytes, str]:
    if not isinstance(payload, Mapping):
        raise ShimTransportError('invalid_response')
    if set(payload) == {'error'}:
        code = payload['error']
        if not isinstance(code, str) or not _CODE_RE.match(code):
            raise ShimTransportError('invalid_response')
        raise ShimProviderError(code)
    if set(payload) != set(RESPONSE_FIELDS):
        raise ShimTransportError('invalid_response')
    status = payload['status']
    if isinstance(status, bool) or not isinstance(status, int) or (not 100 <= status <= 599):
        raise ShimTransportError('invalid_response')
    raw_headers = payload['headers']
    if not isinstance(raw_headers, Mapping):
        raise ShimTransportError('invalid_response')
    headers: Dict[str, str] = {}
    trusted_names = []
    for name, value in raw_headers.items():
        if not isinstance(name, str) or not isinstance(value, str):
            raise ShimTransportError('invalid_response')
        normalized_name = name.lower()
        if normalized_name == operations.TRUSTED_RESPONSE_URL_HEADER:
            trusted_names.append(name)
        elif normalized_name in ('content-type', 'content-length'):
            headers[normalized_name] = value
        elif normalized_name in (SETTLED_MICROUSD_HEADER, CALL_IDENTITY_HEADER):
            if normalized_name in headers:
                raise ShimTransportError('invalid_response')
            if normalized_name == CALL_IDENTITY_HEADER:
                valid = contracts.SHA256_RE.fullmatch(value) is not None
            else:
                valid = re.fullmatch('0|[1-9][0-9]{0,18}', value) is not None
                valid = valid and int(value) <= 2 ** 63 - 1
            if not valid:
                raise ShimTransportError('invalid_response')
            headers[normalized_name] = value
    if SETTLED_MICROUSD_HEADER in headers and CALL_IDENTITY_HEADER not in headers:
        raise ShimTransportError('invalid_response')
    if len(trusted_names) > 1:
        raise ShimTransportError('invalid_response')
    try:
        body = base64.b64decode(str(payload['body_b64']), validate=True)
    except (TypeError, ValueError) as exc:
        raise ShimTransportError('invalid_response') from exc
    response_url = ''
    if trusted_names:
        try:
            response_url = operations.validate_https_url(raw_headers[trusted_names[0]], max_length=2000, field='response_url')
        except operations.OperationError as exc:
            raise ShimTransportError('invalid_response') from exc
    headers['content-length'] = str(len(body))
    return (status, headers, body, response_url)

